using Azure.AI.Inference;
using Azure.Identity;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public class ChatEvals
{
    private static ReportingConfiguration? s_reportingConfiguration;

    private static IChatClient CreateChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("AZURE_OPENAI_ENDPOINT environment variable is not set.");
        var modelId = Environment.GetEnvironmentVariable("AZURE_OPENAI_MODEL") ?? "gpt-4o-mini";

        return new ChatCompletionsClient(new Uri(endpoint), new DefaultAzureCredential())
            .AsChatClient(modelId);
    }

    private static ReportingConfiguration GetReportingConfiguration()
    {
        s_reportingConfiguration ??= DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(Path.GetTempPath(), "MyApp.Evals"),
            chatConfiguration: new ChatConfiguration(CreateChatClient()),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ]);

        return s_reportingConfiguration;
    }

    [TestMethod]
    public async Task Chat_Response_Is_Coherent()
    {
        await using ScenarioRun scenarioRun =
            await GetReportingConfiguration().CreateScenarioRunAsync(scenarioName: nameof(Chat_Response_Is_Coherent));

        var chatClient = CreateChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        ChatResponse response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenarioRun.EvaluateAsync(messages);

        EvaluationResult result = scenarioRun.EvaluationResult;
        ValidateAllMetricsPass(result);
    }

    [TestMethod]
    public async Task Chat_Response_Is_Relevant()
    {
        await using ScenarioRun scenarioRun =
            await GetReportingConfiguration().CreateScenarioRunAsync(scenarioName: nameof(Chat_Response_Is_Relevant));

        var chatClient = CreateChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain photosynthesis in two sentences.")
        };

        ChatResponse response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenarioRun.EvaluateAsync(messages);

        EvaluationResult result = scenarioRun.EvaluationResult;
        ValidateAllMetricsPass(result);
    }

    [TestMethod]
    public async Task Chat_Response_Handles_FollowUp()
    {
        await using ScenarioRun scenarioRun =
            await GetReportingConfiguration().CreateScenarioRunAsync(scenarioName: nameof(Chat_Response_Handles_FollowUp));

        var chatClient = CreateChatClient();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is 2 + 2?")
        };

        ChatResponse response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        messages.Add(new ChatMessage(ChatRole.User, "Now multiply that result by 3."));

        response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenarioRun.EvaluateAsync(messages);

        EvaluationResult result = scenarioRun.EvaluationResult;
        ValidateAllMetricsPass(result);
    }

    private static void ValidateAllMetricsPass(EvaluationResult result)
    {
        foreach (EvaluationMetric metric in result.Metrics.Values)
        {
            if (metric is NumericMetric numericMetric)
            {
                Assert.IsTrue(
                    numericMetric.Value >= 3,
                    $"Metric '{metric.Name}' scored {numericMetric.Value}, which is below the threshold of 3.");
            }
        }
    }
}

